CREATE TABLE brand_profiles (id uuid PRIMARY KEY, tenant_id uuid NOT NULL UNIQUE, name text NOT NULL, introduction text, slogan text, logo_url text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE brand_assets (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, asset_type text NOT NULL, name text NOT NULL, url text, body text, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE brand_contents (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, source_type text NOT NULL, source_id text NOT NULL, title text NOT NULL, snapshot jsonb NOT NULL DEFAULT '{}', link_mode text NOT NULL DEFAULT 'reference', UNIQUE(tenant_id,source_type,source_id));
CREATE TABLE brand_channels (id text NOT NULL, tenant_id uuid NOT NULL, name text NOT NULL, channel_type text NOT NULL, adapter text NOT NULL, enabled boolean NOT NULL DEFAULT true, metadata jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(tenant_id,id));
CREATE TABLE brand_distribution_tasks (id uuid PRIMARY KEY, tenant_id uuid NOT NULL, content_id uuid NOT NULL, channel_ids jsonb NOT NULL, status text NOT NULL, schedule_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE brand_distribution_records (id uuid PRIMARY KEY, task_id uuid NOT NULL, channel_id text NOT NULL, status text NOT NULL, external_url text, impressions bigint NOT NULL DEFAULT 0, backlinks int NOT NULL DEFAULT 0, inquiries int NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now());
